import Observation

@Observable
final class FeedModel {          // implicitly @MainActor (default isolation)
    var items: [Item] = []
    var isLoading = false
    var error: Error?

    func load() async {
        guard !isLoading else { return }
        isLoading = true
        defer { isLoading = false }

        do {
            items = try await Self.fetchItems(from: feedURL)
        } catch is CancellationError {
            // view went away; nothing to do
        } catch {
            self.error = error
        }
    }

    @concurrent
    private static func fetchItems(from url: URL) async throws -> [Item] {
        let (data, _) = try await URLSession.shared.data(from: url)
        return Parser.parse(data)   // CPU work runs off the main actor
    }
}
